*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--cream);font-family:"Trebuchet MS","Gill Sans",sans-serif;font-size:16px;line-height:1.55}button,a,input{-webkit-tap-highlight-color:transparent}button{font:inherit;cursor:pointer}button:disabled{cursor:default;opacity:.42}a{color:var(--gold);text-underline-offset:4px}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #f3c56a;outline-offset:4px}button:active:not(:disabled){transform:translateY(2px)}.wrap{max-width:1180px;margin:auto;padding:26px 32px 40px}nav{display:flex;justify-content:space-between;gap:18px;font-size:12px;letter-spacing:.1em;text-transform:uppercase;border-bottom:1px solid var(--line);padding-bottom:18px}nav a{text-decoration:none}.open{color:var(--gold)}.open:before{content:"";display:inline-block;width:7px;height:7px;background:#e4b36a;border-radius:50%;margin-right:9px;box-shadow:0 0 12px #e4b36a}header{display:grid;grid-template-columns:1.6fr 1fr;gap:40px;align-items:end;padding:42px 0 28px}.eyebrow{margin:0 0 10px;font:12px "Courier New",monospace;letter-spacing:.19em;color:var(--gold);text-transform:uppercase}h1{font:normal clamp(46px,6vw,78px)/.98 "Palatino Linotype","Book Antiqua",Palatino,serif;letter-spacing:-.035em;margin:0}h1 em{color:var(--gold);font-weight:normal}.intro{color:var(--muted);margin:0;max-width:360px;font-size:16px}.layout{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(320px,1fr);gap:30px;align-items:start}.scene{position:relative;isolation:isolate;overflow:hidden;aspect-ratio:3/2;border:1px solid #667366;border-radius:100px 100px 4px 4px;background:radial-gradient(ellipse at 53% 25%,#c49958 0,transparent 40%),linear-gradient(100deg,#0b2632,#4f5140 70%,#243e3c)}.scene img{width:100%;height:auto;display:block;opacity:.9}.scene:after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 -40px 80px #0a201c88}.scene-sign{position:absolute;left:22px;top:24px;font:12px "Courier New",monospace;letter-spacing:.15em;background:#142f2de0;border:1px solid #c5b08a;color:var(--gold);padding:9px 12px;z-index:2}.saucer{position:absolute;width:42%;height:9%;border-radius:50%;background:#e7ddc7;bottom:12%;left:29%;box-shadow:0 7px 0 #b7b9a7,0 15px 25px #061c2280;z-index:3}.cup{position:absolute;width:27%;height:31%;left:36.5%;bottom:17%;border-radius:7px 7px 24px 24px;background:linear-gradient(100deg,#fff9df,#d2d4bf);box-shadow:inset -13px 0 13px #5d645421,0 5px 14px #0005;z-index:4}.cup:after{content:"";position:absolute;width:37%;height:53%;border:10px solid #d7d7bf;border-left:0;border-radius:0 70% 70% 0;left:98%;top:17%;z-index:-1}.surface{position:absolute;top:-5%;left:3%;width:94%;height:15%;border-radius:50%;border:6px solid #fff5d9;background:var(--drink);transition:background .35s}.cup-mark{position:absolute;left:0;right:0;top:30%;text-align:center;font:italic clamp(16px,2.6vw,29px) Palatino,serif;color:#65725d}.steam{position:absolute;bottom:102%;left:24%;width:15%;height:55%;border-left:2px solid #fff3;border-radius:50%;animation:steam 4s infinite ease-in-out}.steam:nth-child(2){left:65%;animation-delay:1.3s}.steam:nth-child(3){left:45%;animation-delay:2.1s}.scene-caption{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-top:14px;font:12px "Courier New",monospace;color:var(--muted)}.dots{display:flex;gap:7px}.dots i{display:block;width:12px;height:12px;border:1px solid #c0af83;border-radius:50%;transition:background .3s}.dots i.done{background:var(--gold);box-shadow:0 0 10px #ecc78366}.ticket{background:var(--cream);color:var(--ink);padding:26px 28px 30px;position:relative;box-shadow:5px 7px 0 #0c2525}.ticket:after{content:"";position:absolute;height:10px;bottom:-9px;left:0;right:0;background:linear-gradient(135deg,var(--cream) 25%,transparent 25%) -5px 0/10px 10px,linear-gradient(225deg,var(--cream) 25%,transparent 25%) -5px 0/10px 10px}.ticket-meta{display:flex;justify-content:space-between;gap:10px;font:11px "Courier New",monospace;letter-spacing:.12em;text-transform:uppercase;border-bottom:1px dashed #9a9e87;padding-bottom:12px}.ticket h2{font:normal 30px/1.15 Palatino,serif;margin:20px 0 9px}.order-note{font-size:14px;line-height:1.5;margin:0 0 15px}.clues{padding:0;list-style:none;margin:0;font-size:14px}.clues li{padding:6px 0 6px 23px;position:relative;border-top:1px solid #dddbc5}.clues li:before{content:"◇";position:absolute;left:0;color:#8a5938}.sticker{display:inline-block;color:#703c2b;border:1px solid #ad7750;border-radius:50%;padding:9px 13px;transform:rotate(-9deg);font:12px "Courier New",monospace;margin-top:16px}.station{margin-top:24px}.station-top{display:flex;align-items:baseline;justify-content:space-between;gap:12px}.station h2{font:normal 24px Palatino,serif;margin:0}.scoop-count{font:13px "Courier New",monospace;color:var(--gold)}.tokens{display:flex;gap:5px;margin:12px 0 15px}.tokens span{height:5px;flex:1;border:1px solid #728278}.tokens .filled{background:var(--gold);border-color:var(--gold)}.ingredients{display:grid;grid-template-columns:1fr 1fr;gap:10px}.ingredient{background:#213c3c;border:1px solid var(--line);padding:14px 12px 12px;border-top:4px solid var(--jar)}.ingredient strong{font-size:15px}.ingredient small{display:block;color:var(--muted);font-size:11px;margin:0 0 12px}.stepper{display:flex;align-items:center;justify-content:space-between;gap:8px}.stepper button{background:transparent;color:var(--cream);border:1px solid #7c9185;border-radius:50%;width:40px;height:40px;line-height:1;font-size:23px}.stepper output{font:23px "Courier New",monospace;min-width:20px;text-align:center}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.primary{background:var(--gold);border:1px solid var(--gold);color:#1b3432;padding:12px 20px;font-weight:bold;flex:1}.quiet{background:transparent;border:1px solid #89998a;color:var(--cream);padding:10px 14px;font-size:13px}.taste{margin-top:26px;padding:21px 22px;background:#102a2d;border-left:3px solid var(--gold)}.taste h3{font:normal 23px Palatino,serif;margin:0 0 8px}.taste p{font-size:14px;color:#cbd4c5;margin:0;white-space:pre-line}.hint-row{margin-top:14px;display:flex;gap:12px;align-items:center}.text-button{padding:5px 0;background:none;border:0;color:var(--gold);text-decoration:underline;text-underline-offset:4px;font-size:13px}.hint{font-size:12px;color:var(--muted)}.next{width:100%;margin-top:17px}.guide{border-top:1px solid var(--line);margin-top:34px;padding-top:18px;font-size:13px;color:var(--muted)}.guide summary{cursor:pointer;color:var(--cream);font-size:15px}.guide ul{padding-left:20px}.guide li{margin:7px 0}.final{margin-top:24px;border:1px solid var(--gold);padding:25px}.final h2{font:normal 33px Palatino,serif;margin:0 0 10px}.final p{color:var(--muted)}.final input{width:100%;padding:12px;color:var(--ink);background:var(--cream);border:0;margin:5px 0 14px;font:18px Palatino,serif}footer{border-top:1px solid var(--line);margin-top:40px;padding-top:23px;font-size:12px;color:var(--muted);max-width:760px}footer p{margin:0 0 10px}[hidden]{display:none!important}.finished .cup{animation:cheers .7s ease}.how{color:var(--muted);font-size:13px;margin:0 0 15px}.tiny{font:11px "Courier New",monospace;color:var(--muted)}
@keyframes steam{0%,100%{opacity:0;transform:translateY(10px) rotate(-7deg)}50%{opacity:1;transform:translateY(-14px) rotate(10deg)}}@keyframes cheers{50%{transform:translateY(-12px) rotate(-5deg)}}@media(max-width:760px){.layout>section{display:contents}.cafe-plate{order:1}.ticket{order:2}.station{order:3}.taste{order:4}.hint-row{order:5}.guide{order:6}.layout{gap:18px}.wrap{padding:22px 18px 35px}header{display:block;padding:30px 0 25px}h1{font-size:clamp(42px,11vw,58px)}.intro{margin-top:20px;max-width:500px}.layout{grid-template-columns:1fr;gap:25px}.scene{max-height:390px;aspect-ratio:3/2}.ticket{padding:24px}.scene-sign{font-size:10px;top:22px;left:18px}.cup-mark{font-size:28px}nav{font-size:10px;letter-spacing:.05em}.station{margin-top:24px}.taste{margin-top:22px}}@media(max-width:350px){h1{font-size:42px}.wrap{padding-left:14px;padding-right:14px}.ingredient{padding:12px 9px}.stepper button{width:38px;height:38px}.ticket{padding:21px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important}}@media print{body{color:#172f31;background:white}.wrap{max-width:700px}nav,header,.layout,.guide,footer,.final .actions,.final input,.final label{display:none!important}.final{display:block!important;color:#172f31;border:2px solid #172f31}.final p{color:#172f31}.final:before{content:"THE MIDNIGHT MALT COUNTER";font:12px monospace;letter-spacing:.15em}}
.scene .saucer{display:none}.scene .cup{width:19%;height:25%;left:39.7%;bottom:29.2%}.scene .cup-mark{font-size:clamp(12px,1.9vw,23px)}@media(max-width:760px){.scene .cup-mark{font-size:clamp(14px,4vw,23px)}}
