<body>
<div class="wrap">
<nav><a href="index.php">← Chloe reads Jon</a><span class="open">Open late · Imaginary drinks</span></nav>
<header><div><p class="eyebrow">A small mystery, served warm</p><h1>The Midnight<br><em>Malt Counter.</em></h1></div><p class="intro">The usual drink has run out. The next one might be wonderful. Or a little weird. Take the late shift and find out.</p></header>
<main>
<div class="layout">
<section aria-label="Your late-night café">
<div class="cafe-plate"><div class="scene" id="scene">
<img width="1200" height="800" alt="A painted midnight café: rain on the window, an amber pendant lamp, and four coloured ingredient jars beside a waiting saucer." src="data:image/webp;base64,">
<div class="scene-sign">THE NIGHT SHIFT / 11:47 PM</div>
<div class="saucer"></div><div class="cup" role="img" aria-label="A warm ceramic mug; its drink colour changes with your blend"><div class="surface"></div><span class="steam"></span><span class="steam"></span><span class="steam"></span><span class="cup-mark">a little<br>wonder</span></div>
</div>
<div class="scene-caption"><span id="shift">0 of 5 orders served</span><div class="dots" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div></div>
</div><div class="taste" aria-live="polite" aria-atomic="true"><h3 id="verdict">The kettle is on.</h3><p id="feedback">Read the ticket, then use + and − to build a six-scoop blend. Taste as often as you like. Nobody is keeping score.</p></div>
<div class="hint-row"><button class="text-button" id="hintButton">A nudge from the night cook</button><span class="hint" id="hint"></span></div>
<details class="guide"><summary>First shift? Here is how it works.</summary><ul><li>Each mug uses exactly six scoops, with at most four scoops from one jar.</li><li>The ticket describes one secret recipe. All its clues must be true at once.</li><li>Malt is toasty and a little sweet. Cocoa brings chocolate. Milk powder adds creaminess. Sugar brings sweetness.</li><li>A taste tells you which ingredient needs more or less. Use a cook's nudge if you get stuck.</li><li>These are invented puzzle proportions, not real Horlicks or Ovaltine recipes. There is no timer, penalty, or caffeine claim.</li></ul><p>Tip for two players: one person reads the ticket; the other works the jars. Swap jobs for the next customer.</p></details>
</section>
<section aria-label="Order ticket and mixing station">
<div class="ticket"><div class="ticket-meta"><span>Midnight malt counter</span><span id="orderNo">No. 01 / 05</span></div><h2 id="customer"></h2><p class="order-note" id="orderNote"></p><ul class="clues" id="clues"></ul><div class="sticker">6 SCOOPS<br>ONE WARM MUG</div></div>
<div class="station" id="station"><div class="station-top"><h2>The four jars</h2><span class="scoop-count" id="count" aria-live="polite">0 / 6 scoops</span></div><div class="tokens" id="tokens" aria-hidden="true"></div><p class="how">Tap to add or remove a scoop. Four per jar, six in total.</p><div class="ingredients" id="ingredients"></div><div class="actions"><button class="primary" id="tasteButton">Taste this blend →</button><button class="quiet" id="emptyButton">Empty mug</button></div><button class="primary next" id="nextButton" hidden>Next customer →</button></div>
</section>
</div>
<section class="final" id="final" hidden aria-live="polite"><p class="eyebrow">The kettle takes a bow</p><h2 id="finalTitle">Keeper of the midnight kettle</h2><p id="finalNote">Five customers, five warm mugs. Your night shift is complete. Now invent the house special.</p><label for="blendName">Name your imaginary house blend</label><input id="blendName" maxlength="48" value="The Slightly Weird & Wonderful" autocomplete="off"><p id="recipeCard"></p><div class="actions"><button class="primary" id="houseButton">Mix a house special</button><button class="quiet" id="saveButton">Save tasting card</button><button class="quiet" id="printButton">Print card</button><button class="quiet" id="restartButton">Start a fresh shift</button></div></section>
<noscript><p>This little mixing puzzle needs JavaScript. You can still <a href="?source=1">read the post that inspired it</a>.</p></noscript>
</main>
<footer><p>Inspired by Jon's <a href="?source=1">Horlicks drink</a>, his 2010 account of trying an unfamiliar malt drink in a late-night Chinese restaurant. His review: “It's alright. It's kind of weird.”</p><p>A made-up café and fictional customers. Original café artwork made with GPT Image. Everything happens on this page; no account, sound, or saved progress. <a href="index.php">Back to the collection →</a></p></footer>
</div>
<script>
'use strict';
const jars=[
{name:'Malt',note:'toasty barley',color:'#d9b577'},
{name:'Cocoa',note:'deep chocolate',color:'#a47a60'},
{name:'Milk powder',note:'soft & creamy',color:'#e9e3cb'},
{name:'Sugar',note:'a sweet finish',color:'#d29d94'}
];
const orders=[
{name:'The curious newcomer',note:'“Ovaltine is out? All right. Surprise me with something toasty.”',clues:['No cocoa tonight.','Use one scoop of sugar.','Malt gets one more scoop than milk powder.'],recipe:[3,0,2,1],reply:'Toasty, creamy, and pleasantly unfamiliar. The customer considers a second mug. A quiet triumph.'},
{name:'The crossword regular',note:'“Balance, please. My crossword has enough drama already.”',clues:['Malt and cocoa get the same number of scoops.','Milk powder and sugar get the same number.','Use twice as much malt as milk powder.'],recipe:[2,2,1,1],reply:'Everything in proportion. The crossword remains unsolved, but the drink is beyond reproach.'},
{name:'The chocolate loyalist',note:'“Chocolate first. Sweetness can take the evening off.”',clues:['No sugar.','Cocoa gets one more scoop than milk powder.','Milk powder gets one more scoop than malt.'],recipe:[1,3,2,0],reply:'A chocolate-forward mug with a little barley underneath. The loyalist nods. This is apparently a standing ovation.'},
{name:'The barley enthusiast',note:'“I came for the malt. Please do not let it be shy.”',clues:['No cocoa.','Milk powder and sugar get the same number.','Malt gets two scoops more than milk powder and sugar combined.'],recipe:[4,0,1,1],reply:'Unmistakably malty. If barley could write a thank-you letter, this would be the occasion.'},
{name:'The last tram passenger',note:'“Something sweet before the last tram. I am walking slowly on purpose.”',clues:['Sugar gets as many scoops as all three other jars combined.','Malt, cocoa, and milk powder get equal shares.'],recipe:[1,1,1,3],reply:'A sweet little send-off into the rain. The last tram waits just long enough. You turn the sign around.'}
];
const $=id=>document.getElementById(id);
let current=0,blend=[0,0,0,0],solved=false,served=0,hintIndex=0,house=false;
const total=()=>blend.reduce((a,b)=>a+b,0);
function initJars(){
$('ingredients').innerHTML=jars.map((j,i)=>'<div class="ingredient" style="--jar:'+j.color+'"><strong>'+j.name+'</strong><small>'+j.note+'</small><div class="stepper"><button type="button" data-jar="'+i+'" data-change="-1" aria-label="Remove a scoop of '+j.name+'">−</button><output id="amount'+i+'" aria-label="'+j.name+' scoops">0</output><button type="button" data-jar="'+i+'" data-change="1" aria-label="Add a scoop of '+j.name+'">+</button></div></div>').join('');
$('tokens').innerHTML='<span></span>'.repeat(6);
}
function refresh(){
const t=total();
$('count').textContent=t+' / 6 scoops';
document.querySelectorAll('#tokens span').forEach((e,i)=>e.classList.toggle('filled',i<t));
jars.forEach((j,i)=>{$('amount'+i).textContent=blend[i]});
document.querySelectorAll('[data-change]').forEach(b=>{const i=Number(b.dataset.jar),change=Number(b.dataset.change);b.disabled=solved||(!house&&served===5)||(change>0?(t>=6||blend[i]>=4):blend[i]<=0)});
$('tasteButton').disabled=solved||t!==6||(!house&&served===5);
$('emptyButton').disabled=solved||t===0||(!house&&served===5);
$('hintButton').disabled=house||solved||served===5;
const cocoa=blend[1],milk=blend[2],malt=blend[0];
const light=70-cocoa*8+milk*3-malt*1.5;
document.documentElement.style.setProperty('--drink',t?'hsl(31 39% '+light+'%)':'#e2dfc8');
$('scene').classList.toggle('finished',solved);
if(house)updateCard();
}
function loadOrder(){
blend=[0,0,0,0];solved=false;hintIndex=0;house=false;
const o=orders[current];
$('orderNo').textContent='No. '+String(current+1).padStart(2,'0')+' / 05';
$('customer').textContent=o.name;$('orderNote').textContent=o.note;
$('clues').replaceChildren(...o.clues.map(c=>{let li=document.createElement('li');li.textContent=c;return li}));
$('hint').textContent='';$('nextButton').hidden=true;$('tasteButton').textContent='Taste this blend →';
$('verdict').textContent=current?'A fresh ticket, a fresh mug.':'The kettle is on.';
$('feedback').textContent='Build a six-scoop blend that fits every clue. A taste will tell you what needs adjusting.';
refresh();
}
$('ingredients').addEventListener('click',e=>{
const b=e.target.closest('[data-change]');if(!b||b.disabled)return;
blend[Number(b.dataset.jar)]+=Number(b.dataset.change);refresh();
});
$('emptyButton').addEventListener('click',()=>{if(solved)return;blend=[0,0,0,0];$('verdict').textContent='A clean mug.';$('feedback').textContent='The kettle is patient. Try another combination.';refresh()});
$('tasteButton').addEventListener('click',()=>{
if(total()!==6||solved)return;
if(house){
$('verdict').textContent='The house special is served.';
const dominant=blend.indexOf(Math.max(...blend));
$('feedback').textContent=['Warm barley takes the lead. A rainy-window sort of drink.','Chocolate gets the best seat in the house. Quite right.','Soft, creamy, and in absolutely no hurry.','The sweet tooth has spoken. It appears to have a microphone.'][dominant];
updateCard();return;
}
const o=orders[current],notes=[];
jars.forEach((j,i)=>{if(blend[i]!==o.recipe[i])notes.push(j.name+': '+(blend[i]<o.recipe[i]?'a little more, please.':'a little less, please.'))});
if(notes.length){$('verdict').textContent='Almost a regular.';$('feedback').textContent=notes.join('\n');return}
solved=true;served=current+1;
$('verdict').textContent='Exactly their cup of malt.';$('feedback').textContent=o.reply;
$('shift').textContent=served+' of 5 orders served';
document.querySelectorAll('.dots i').forEach((e,i)=>e.classList.toggle('done',i<served));
$('nextButton').hidden=false;$('nextButton').textContent=served===5?'Finish the night shift →':'Next customer →';refresh();
});
$('hintButton').addEventListener('click',()=>{
if(solved||house)return;
const i=hintIndex++%4,n=orders[current].recipe[i];
$('hint').textContent=jars[i].name+': '+n+' scoop'+(n===1?'':'s')+'.';
});
$('nextButton').addEventListener('click',()=>{
if(!solved)return;
if(current<orders.length-1){current++;loadOrder();$('customer').tabIndex=-1;$('customer').focus()}
else{$('final').hidden=false;$('nextButton').hidden=true;updateCard();$('final').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})}
});
function recipeText(){return jars.map((j,i)=>blend[i]+' '+j.name.toLowerCase()).join(' · ')}
function updateCard(){
const name=$('blendName').value.trim()||'The unnamed house special';
$('finalTitle').textContent=name;
$('recipeCard').textContent='Your imaginary six-scoop recipe: '+recipeText()+'.';
if(total()===6)$('finalNote').textContent='Five customers, five warm mugs. Your night shift is complete. Now invent the house special.';
}
$('blendName').addEventListener('input',updateCard);
$('houseButton').addEventListener('click',()=>{
house=true;solved=false;blend=[0,0,0,0];
$('orderNo').textContent='HOUSE / SPECIAL';$('customer').textContent='Your counter. Your concoction.';
$('orderNote').textContent='The customers have gone home. Make something you would order again.';
const li=document.createElement('li');li.textContent='Six scoops. Any combination. There is no wrong answer.';
$('clues').replaceChildren(li);$('hint').textContent='';$('tasteButton').textContent='Taste the house special →';$('verdict').textContent='A little after-hours experiment.';$('feedback').textContent='Build your own six-scoop drink, give it a name below, and save the tasting card.';
refresh();$('station').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
});
function cardText(){return 'THE MIDNIGHT MALT COUNTER\n'+($('blendName').value.trim()||'The unnamed house special')+'\n\n'+recipeText()+'\n\nAn imaginary six-scoop blend, not a real product recipe.\nNight shift: five orders served.\nInspired by Jon’s Horlicks drink post (October 2010).\n'}
$('saveButton').addEventListener('click',()=>{
if(total()!==6){$('finalNote').textContent='Put all six scoops in your house special before saving its card.';return}
const url=URL.createObjectURL(new Blob([cardText()],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');
a.href=url;a.download='midnight-malt-tasting-card.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
});
$('printButton').addEventListener('click',()=>{if(total()!==6){$('finalNote').textContent='Finish your six-scoop blend before printing.';return}window.print()});
$('restartButton').addEventListener('click',()=>{
current=0;served=0;house=false;$('final').hidden=true;$('blendName').value='The Slightly Weird & Wonderful';$('finalNote').textContent='Five customers, five warm mugs. Your night shift is complete. Now invent the house special.';
$('shift').textContent='0 of 5 orders served';document.querySelectorAll('.dots i').forEach(e=>e.classList.remove('done'));loadOrder();window.scrollTo({top:0,behavior:'instant'});
});
initJars();loadOrder();
</script>
</body>
</html>
